import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String[] line = scanner.nextLine().split(" ");
        int n = Integer.parseInt(line[0]);
        int h = Integer.parseInt(line[1]);

        int[][] array_nodes_minheight = new int[36][36];

        array_nodes_minheight[0][0] = 1;

        for (int nodes = 1; nodes < 36; nodes++) {
            for (int minheight = 0; minheight <= nodes; minheight++) {
                long sum = 0;
                for (int topnode = 1; topnode <= nodes; topnode++) {
                    int left = topnode - 1;
                    int right = nodes - topnode;
                    long leftZero = array_nodes_minheight[left][0];
                    long rightZero = array_nodes_minheight[right][0];

                    long leftMax = array_nodes_minheight[left][Math.max(minheight - 1, 0)];
                    long rightMax = array_nodes_minheight[right][Math.max(minheight - 1, 0)];

                    sum += leftZero * rightZero - (leftZero - leftMax) * (rightZero - rightMax);
                }
                array_nodes_minheight[nodes][minheight] = (int) sum;
            }
        }

        System.out.println(array_nodes_minheight[n][h]);
        scanner.close();
    }
}
